export const VEML_NAMESPACE_3_0 = 'http://www.fivesqd.com/schemas/veml/3.0';
export const VEML_NAMESPACE_3_1 = 'http://www.fivesqd.com/schemas/veml/3.1';
export const SUPPORTED_VEML_NAMESPACES = [VEML_NAMESPACE_3_0, VEML_NAMESPACE_3_1] as const;
const XSI_NS = 'http://www.w3.org/2001/XMLSchema-instance';

// ---------------------------------------------------------------------------
// Parse report — the contract the capability registry and the error surface
// consume. Keep shapes stable.
// ---------------------------------------------------------------------------

export interface VemlParseError {
  kind: 'fetch' | 'malformed-xml' | 'not-veml' | 'unsupported-namespace' | 'served-html' | 'refused';
  message: string;
  url?: string;
  /**
   * `refused` is set by the session and never raised here: the page does not
   * open worlds from the address's origin. The message says which address and
   * which origins the page does open, in words for the visitor.
   */
  /**
   * `served-html` is set by loadWorld and never raised here, because only the
   * fetch layer sees a content-type. It means the address answered with a web
   * page rather than a world document — overwhelmingly a missing file behind
   * a dev server or a static host with SPA fallback, both of which reply 200
   * with their own shell.
   */
  /**
   * `fetch` kind only — set by loadWorld, never here:
   * `http` = the server answered with an error status; `network` = the fetch
   * rejected before a response existed (offline, DNS, or a cross-origin
   * server without CORS headers — the error card's CORS-hint signal).
   */
  phase?: 'network' | 'http' | 'integrity';
}

export interface VemlParseWarning {
  kind:
    | 'unknown-element'
    | 'unknown-attribute'
    | 'unknown-entity-type'
    | 'unknown-transform-type'
    | 'invalid-attribute-value'
    /** A veml:<section>:<slug> diagnostic surfaced by the 4.0
     *  path (packages/veml-parse), or a shell-local `veml:4.0-port:*` note
     *  for a 4.0 surface the shell defers. `name` carries the id, `path`
     *  the detail. */
    | 'diagnostic';
  /** The offending element/attribute/type name as found on the wire. */
  name: string;
  /** Locates the node, e.g. `environment > entity[2] > entity[0]`. */
  path: string;
}

export interface VemlParseReport {
  url: string;
  /** null when the document failed before/at version classification. */
  declaredVersion: VemlDeclaredVersion | null;
  errors: VemlParseError[];
  warnings: VemlParseWarning[];
}

export type VemlParseResult =
  | { ok: true; document: VemlDocument; report: VemlParseReport }
  | { ok: false; report: VemlParseReport };

// ---------------------------------------------------------------------------
// Root-tag scan + xmlns:xsi normalization (A.3).
// ---------------------------------------------------------------------------

/** Find the root element's open tag (start/end indices), skipping XML decl, comments, PIs, DOCTYPE. */
function scanRootTag(text: string): { start: number; end: number } | null {
  let i = 0;
  while (i < text.length) {
    const lt = text.indexOf('<', i);
    if (lt < 0) return null;
    let skipTo: number;
    if (text.startsWith('<?', lt)) skipTo = text.indexOf('?>', lt) + 2;
    else if (text.startsWith('<!--', lt)) skipTo = text.indexOf('-->', lt) + 3;
    else if (text.startsWith('<!', lt)) skipTo = text.indexOf('>', lt) + 1;
    else {
      // Quote-aware end-of-tag scan: '>' is legal inside attribute values
      // (<veml note="a>b">) and must not terminate the open tag there.
      let quote: string | null = null;
      for (let j = lt + 1; j < text.length; j++) {
        const ch = text[j];
        if (quote) {
          if (ch === quote) quote = null;
        } else if (ch === '"' || ch === "'") quote = ch;
        else if (ch === '>') return { start: lt, end: j };
      }
      return null;
    }
    if (skipTo < lt) return null; // unterminated construct
    i = skipTo;
  }
  return null;
}

/**
 * Inject `xmlns:xsi` into the root open tag when absent — the minimum needed
 * for `xsi:type` to parse. The tag is found by scanning rather than by a
 * literal `<veml>` replacement, so roots that carry attributes are handled
 * too.
 */
function normalizeRootTag(text: string): string {
  const scan = scanRootTag(text);
  if (!scan || /xmlns:xsi\s*=/.test(text.slice(scan.start, scan.end + 1))) return text;
  const selfClosing = text[scan.end - 1] === '/';
  const insertAt = scan.end - (selfClosing ? 1 : 0);
  return text.slice(0, insertAt) + ` xmlns:xsi="${XSI_NS}"` + text.slice(insertAt);
}

// ---------------------------------------------------------------------------
// DOM helpers — all matching is by localName so namespaced (qualified) and
// namespace-less documents share one code path.
// ---------------------------------------------------------------------------

function elementChildren(el: Element): Element[] {
  return Array.from(el.children);
}

function childrenNamed(el: Element, name: string): Element[] {
  return elementChildren(el).filter((c) => c.localName === name);
}

function childNamed(el: Element, name: string): Element | undefined {
  return childrenNamed(el, name)[0];
}

function text(el: Element | undefined): string | undefined {
  return el ? (el.textContent ?? '').trim() : undefined;
}

function attr(el: Element, name: string): string | undefined {
  return el.getAttribute(name) ?? undefined;
}

/** Read `xsi:type`, tolerating both proper-namespace and raw-attribute forms; strip any prefix. */
function readXsiType(el: Element): string | undefined {
  // .NET XmlSerializer trims QName whitespace; mirror it (oracle parity).
  const value = (el.getAttributeNS(XSI_NS, 'type') ?? el.getAttribute('xsi:type'))?.trim();
  if (!value) return undefined;
  const colon = value.indexOf(':');
  return colon >= 0 ? value.slice(colon + 1) : value;
}

function parseNumber(raw: string | null | undefined, fallback: number): number {
  if (raw === null || raw === undefined || raw.trim() === '') return fallback;
  const n = Number(raw);
  return Number.isFinite(n) ? n : fallback;
}

function parseBool(raw: string | null | undefined, fallback: boolean): boolean {
  const v = raw?.trim().toLowerCase();
  return v === 'true' || v === '1' ? true : v === 'false' || v === '0' ? false : fallback;
}

function optNum(el: Element | undefined): number | undefined {
  const t = text(el);
  if (!t) return undefined;
  const n = Number(t);
  return Number.isFinite(n) ? n : undefined;
}

function numAttr(el: Element, name: string): number | undefined {
  const raw = el.getAttribute(name);
  return raw === null ? undefined : parseNumber(raw, 0);
}

function boolAttr(el: Element, name: string): boolean | undefined {
  const raw = el.getAttribute(name);
  return raw === null ? undefined : parseBool(raw, false);
}

function vec3(el: Element | undefined, defaults: Readonly<VemlVec3>): VemlVec3 {
  return {
    x: parseNumber(el?.getAttribute('x'), defaults.x),
    y: parseNumber(el?.getAttribute('y'), defaults.y),
    z: parseNumber(el?.getAttribute('z'), defaults.z),
  };
}

function quat(el: Element | undefined): VemlQuaternion {
  return {
    x: parseNumber(el?.getAttribute('x'), DEFAULT_ROTATION.x),
    y: parseNumber(el?.getAttribute('y'), DEFAULT_ROTATION.y),
    z: parseNumber(el?.getAttribute('z'), DEFAULT_ROTATION.z),
    w: parseNumber(el?.getAttribute('w'), DEFAULT_ROTATION.w),
  };
}

function vec2(el: Element | undefined, defaults: Readonly<VemlVec2>): VemlVec2 {
  return {
    x: parseNumber(el?.getAttribute('x'), defaults.x),
    y: parseNumber(el?.getAttribute('y'), defaults.y),
  };
}

// ---------------------------------------------------------------------------
// Unknown-content detection (A.8).
// ---------------------------------------------------------------------------

class WarningSink {
  readonly warnings: VemlParseWarning[] = [];

  add(kind: VemlParseWarning['kind'], name: string, path: string): void {
    this.warnings.push({ kind, name, path });
  }

  /** Warn on element children whose localName is not in `expected`. */
  checkChildren(el: Element, expected: readonly string[], path: string): void {
    for (const child of elementChildren(el)) {
      if (!expected.includes(child.localName)) {
        this.add('unknown-element', child.localName, path);
      }
    }
  }

  /** Warn on attributes not in `expected` (xmlns/xsi machinery is never unknown). */
  checkAttributes(el: Element, expected: readonly string[], path: string): void {
    for (const a of Array.from(el.attributes)) {
      const name = a.name;
      if (name === 'xmlns' || name.startsWith('xmlns:') || name.startsWith('xsi:')) continue;
      if (a.namespaceURI === XSI_NS) continue;
      if (!expected.includes(a.localName)) this.add('unknown-attribute', name, path);
    }
  }
}

// ---------------------------------------------------------------------------
// Transforms (A.5, A.6).
// ---------------------------------------------------------------------------

function parseTransform(
  el: Element,
  path: string,
  sink: WarningSink,
): VemlTransform | undefined {
  const kind = readXsiType(el);
  sink.checkAttributes(
    el,
    kind === 'canvastransform'
      ? ['align-horizontal', 'align-vertical', 'stretch-to-parent']
      : [],
    path,
  );
  if (kind === 'scaletransform' || kind === 'sizetransform') {
    const sizeName = kind === 'scaletransform' ? 'scale' : 'size';
    sink.checkChildren(el, ['position', 'rotation', sizeName], path);
    const position = vec3(childNamed(el, 'position'), DEFAULT_POSITION);
    const rotation = quat(childNamed(el, 'rotation'));
    return kind === 'scaletransform'
      ? { kind, position, rotation, scale: vec3(childNamed(el, 'scale'), DEFAULT_SCALE) }
      : { kind, position, rotation, size: vec3(childNamed(el, 'size'), DEFAULT_SIZE) };
  }
  if (kind === 'canvastransform') {
    sink.checkChildren(el, ['position-percent', 'size-percent'], path);
    const alignH = attr(el, 'align-horizontal');
    const alignV = attr(el, 'align-vertical');
    return {
      kind,
      positionPercent: vec2(childNamed(el, 'position-percent'), DEFAULT_POSITION_PERCENT),
      sizePercent: vec2(childNamed(el, 'size-percent'), DEFAULT_SIZE_PERCENT),
      alignHorizontal: alignH as 'center' | 'left' | 'right' | undefined,
      alignVertical: alignV as 'center' | 'top' | 'bottom' | undefined,
      stretchToParent: boolAttr(el, 'stretch-to-parent'),
    };
  }
  // Missing or unrecognized transform xsi:type — warn, transform absent
  // (the XSD's abstract basetransform REQUIRES xsi:type; real corpus docs
  // that omit it exist, so this must not hard-fail).
  sink.add('unknown-transform-type', kind ?? '(missing xsi:type)', path);
  return undefined;
}

// ---------------------------------------------------------------------------
// Entities (A.5) — base slots + per-subtype payloads.
//
// The payloads are TABLE-DRIVEN (bundle size: a per-type switch minified ~2 KB
// gzip heavier). Each subtype maps model keys to wire names + a field kind; the
// unknown-element/-attribute allowlists are DERIVED from the same
// tables so they cannot drift. Kinds:
//   s  element text (optional)         n  element number (optional)
//   be element bool w/ default         ne element number w/ default
//   r  element URI ref (resolved)      rs repeated element URI refs
//   v3 element vec3 (optional)         q  element quaternion (optional)
//   as attr string                     aD attr string w/ default
//   an attr number                     ab attr bool
//   ar attr URI ref (resolved)         L  nested element list w/ sub-spec
// ---------------------------------------------------------------------------

// Exported: the HTML dialect front-end
// (src/veml/htmlDialect.ts) reuses this SAME field catalog so the two input
// syntaxes cannot drift — the dialect reads each `wire` name as an ATTRIBUTE
// rather than a child element, but the [key, wire, kind, dflt] table is
// single-source here. No behavior change; these were module-private.
export type FieldKind =
  | 's' | 'n' | 'be' | 'ne' | 'r' | 'rs' | 'v3' | 'q'
  | 'as' | 'aD' | 'an' | 'ab' | 'ar' | 'L';
export type FieldSpec = ReadonlyArray<
  readonly [key: string, wire: string, kind: FieldKind, dflt?: unknown]
>;

export const ATTR_KINDS: readonly FieldKind[] = ['as', 'aD', 'an', 'ab', 'ar'];

const MESH_FIELDS: FieldSpec = [
  ['meshName', 'mesh-name', 's'],
  ['meshResources', 'mesh-resource', 'rs'],
];
const PRIMITIVE_FIELDS: FieldSpec = [['color', 'color', 's']];

