for (const t of VEML_ENTITY_TYPES) {
  if (!(t in SUBTYPE_FIELDS)) SUBTYPE_FIELDS[t] = PRIMITIVE_FIELDS;
}

const BASE_ENTITY_CHILDREN = ['transform', 'entity', 'synchronizer', 'placement-socket', 'link'];
const BASE_ENTITY_ATTRS = ['tag', 'id', 'on-load-event'];

/** Apply a field spec to an element, writing model keys into `out`. */
function applyFields(
  el: Element,
  spec: FieldSpec,
  out: Record<string, unknown>,
  worldDocUrl: string,
): void {
  const ref = (raw: string): VemlResourceRef => ({
    raw,
    resolved: resolveWorldUri(raw, worldDocUrl),
  });
  for (const [key, wire, kind, dflt] of spec) {
    const child = childNamed(el, wire);
    let value: unknown;
    switch (kind) {
      case 's': value = text(child); break;
      case 'n': value = optNum(child); break;
      case 'be': value = parseBool(text(child), dflt as boolean); break;
      case 'ne': value = parseNumber(text(child), dflt as number); break;
      case 'r': { const t = text(child); value = t ? ref(t) : undefined; break; }
      case 'rs':
        value = childrenNamed(el, wire)
          .map((r) => text(r) ?? '')
          .filter((r) => r !== '')
          .map(ref);
        break;
      case 'v3': value = child ? vec3(child, DEFAULT_POSITION) : undefined; break;
      case 'q': value = child ? quat(child) : undefined; break;
      case 'as': value = attr(el, wire); break;
      case 'aD': value = attr(el, wire) ?? dflt; break;
      case 'an': value = numAttr(el, wire); break;
      case 'ab': value = boolAttr(el, wire); break;
      // Empty string stays absent — ref('') would resolve to the document URL itself.
      case 'ar': { const v = attr(el, wire); value = v ? ref(v) : undefined; break; }
      case 'L':
        value = childrenNamed(el, wire).map((item) => {
          const nested: Record<string, unknown> = {};
          applyFields(item, dflt as FieldSpec, nested, worldDocUrl);
          return nested;
        });
        break;
    }
    out[key] = value;
  }
}

function parsePlacementSocket(el: Element): VemlPlacementSocket {
  return {
    position: vec3(childNamed(el, 'position'), DEFAULT_POSITION),
    rotation: quat(childNamed(el, 'rotation')),
    connectingOffset: vec3(childNamed(el, 'connecting-offset'), DEFAULT_POSITION),
  };
}

function parseEntity(
  el: Element,
  path: string,
  worldDocUrl: string,
  sink: WarningSink,
): VemlEntity {
  const declaredType = readXsiType(el);
  const type = declaredType ?? '';
  // Own-property lookup only: a wire-controlled xsi:type like "constructor"
  // or "toString" must not reach Object.prototype.
  const spec = Object.prototype.hasOwnProperty.call(SUBTYPE_FIELDS, type)
    ? SUBTYPE_FIELDS[type]
    : undefined;
  if (!spec) sink.add('unknown-entity-type', declaredType ?? '(missing xsi:type)', path);

  const fields = spec ?? [];
  sink.checkChildren(
    el,
    [...BASE_ENTITY_CHILDREN, ...fields.filter(([, , k]) => !ATTR_KINDS.includes(k)).map(([, w]) => w)],
    path,
  );
  sink.checkAttributes(
    el,
    [...BASE_ENTITY_ATTRS, ...fields.filter(([, , k]) => ATTR_KINDS.includes(k)).map(([, w]) => w)],
    path,
  );

  // Base slots (shared by every subtype).
  const transformEl = childNamed(el, 'transform');
  const linkEl = childNamed(el, 'link');
  let link: VemlLink | undefined;
  if (linkEl) {
    // VEML 3.1 — FIRST-CLASS, never a warning (A.10).
    const href = attr(linkEl, 'href') ?? '';
    // A link that does not resolve to http(s) is not a portal.
    const resolvedHref = href ? followableWorldUri(href, worldDocUrl) : '';
    link =
      resolvedHref === undefined
        ? undefined
        : { href, resolvedHref, label: (linkEl.textContent ?? '').trim() };
  }
  const base: VemlEntityBase & { known?: false } = {
    type,
    tag: attr(el, 'tag'),
    id: attr(el, 'id'),
    onLoadEvent: attr(el, 'on-load-event'),
    transform: transformEl ? parseTransform(transformEl, `${path} > transform`, sink) : undefined,
    children: childrenNamed(el, 'entity').map((child, i) =>
      parseEntity(child, `${path} > entity[${i}]`, worldDocUrl, sink),
    ),
    synchronizer: text(childNamed(el, 'synchronizer')),
    placementSockets: childrenNamed(el, 'placement-socket').map(parsePlacementSocket),
    link,
  };
  if (!spec) {
    base.known = false;
    return base as VemlEntity;
  }
  applyFields(el, spec, base as unknown as Record<string, unknown>, worldDocUrl);
  return base as VemlEntity;
}

