/**
 * The metadata children the 3.x grammar carries. The HTML dialect reads the
 * same list, so a surface added here without a dialect handler is a type
 * error there, and the parity test holds both to one source.
 */
export const LEGACY_METADATA_CHILDREN = [
  'title',
  'capability',
  'script',
  'inputevent',
  'controlflags',
  'synchronizationservice',
] as const;
export type LegacyMetadataChild = (typeof LEGACY_METADATA_CHILDREN)[number];

function parseMetadata(
  el: Element | undefined,
  worldDocUrl: string,
  sink: WarningSink,
): VemlMetadata {
  const metadata: VemlMetadata = {
    capabilities: [],
    scripts: [],
    inputEvents: [],
    synchronizationServices: [],
  };
  if (!el) return metadata; // A.7 leniency — absent metadata is not fatal.
  sink.checkChildren(el, LEGACY_METADATA_CHILDREN, 'metadata');
  metadata.title = text(childNamed(el, 'title'));
  metadata.capabilities = childrenNamed(el, 'capability').map((c) => text(c) ?? '');
  metadata.scripts = childrenNamed(el, 'script')
    .map((s) => text(s) ?? '')
    .filter((s) => s !== '')
    .map((s) => ({ raw: s, resolved: resolveWorldUri(s, worldDocUrl) }));
  metadata.inputEvents = childrenNamed(el, 'inputevent').map((ie, i) => {
    sink.checkAttributes(ie, ['input', 'event'], `metadata > inputevent[${i}]`);
    return { input: attr(ie, 'input'), event: attr(ie, 'event') };
  });
  const flagsEl = childNamed(el, 'controlflags');
  if (flagsEl) {
    sink.checkChildren(
      flagsEl,
      CONTROL_FLAG_FIELDS.map(([, wire]) => wire),
      'metadata > controlflags',
    );
    const flags: Record<string, string | boolean> = {};
    for (const [key, wire, kind] of CONTROL_FLAG_FIELDS) {
      const raw = text(childNamed(flagsEl, wire));
      if (raw === undefined) continue;
      flags[key] = kind === 'b' ? parseBool(raw, false) : raw;
    }
    metadata.controlFlags = flags as VemlControlFlags;
  }
  metadata.synchronizationServices = childrenNamed(el, 'synchronizationservice').map(
    (svc, i) => {
      sink.checkAttributes(
        svc,
        ['type', 'address', 'id', 'session'],
        `metadata > synchronizationservice[${i}]`,
      );
      return {
        type: attr(svc, 'type'),
        address: attr(svc, 'address'),
        id: attr(svc, 'id'),
        session: attr(svc, 'session'),
      };
    },
  );
  return metadata;
}

/**
 * Lite procedural sky attribute catalog (XSD lines 72–130): wire name →
 * default. The DEFAULT's runtime type selects the parse (boolean/number/
 * string); `undefined` marks the three `use="optional"` strings with no
 * default (sun-entity-tag, star-texture-uri, clouds-texture-uri).
 *
 * Exported: the HTML dialect front-end
 * (src/veml/htmlDialect.ts) reuses this SAME catalog for its `<veml-sky>`
 * lite-procedural-sky background element — reading each wire name as an
 * ATTRIBUTE (identical kebab→camel key + default-typed parse) so the XML
 * `<lite-procedural-sky>` and the dialect `<veml-sky>` cannot drift (proven
 * deep-equal, conformance G.11).
 */
export const SKY_ATTRS: Array<[string, string | number | boolean | undefined]> = [
  ['sun-entity-tag', undefined],
  ['day-night-cycle-enabled', true],
  ['ground-enabled', true],
  ['ground-color', '#07070700'],
  ['ground-height', -0.02],
  ['ground-fade-amount', 0.02],
  ['horizon-sky-blend', 0.579],
  ['day-horizon-color', '#448bc5ff'],
  ['day-sky-color', '#08124100'],
  ['night-horizon-color', '#07050d00'],
  ['night-sky-color', '03010300'],
  ['horizon-saturation-amount', 0.894],
  ['horizon-saturation-falloff', 4.45],
  ['sun-enabled', true],
  ['sun-diameter', 2],
  ['sun-horizon-color', 'color(155 72 33 0)'],
  ['sun-zenith-color', 'color(158 129 58 0)'],
  ['sun-sky-lighting-enabled', true],
  ['sky-lighting-falloff-amount', 10],
  ['sky-lighting-falloff-intensity', 1],
  ['sunset-intensity', 0.3],
  ['sunset-radial-falloff', 0.1],
  ['sunset-horizontal-falloff', 0.6],
  ['sunset-vertical-falloff', 0.5],
  ['moon-enabled', true],
  ['moon-diameter', 2],
  ['moon-color', '#abb9bf00'],
  ['moon-falloff-amount', 60],
  ['stars-enabled', true],
  ['stars-brightness', 0.85],
  ['stars-daytime-brightness', 0.1],
  ['stars-horizon-falloff', 0],
  ['stars-saturation', 0.3],
  ['procedural-stars-enabled', true],
  ['procedural-stars-sharpness', 1],
  ['procedural-stars-amount', 1],
  ['stars-texture-enabled', true],
  ['star-texture-uri', undefined],
  ['star-tint', '#ffffff00'],
  ['star-scale', 0.5],
  ['star-rotation-speed', 0.25],
  ['clouds-enabled', true],
  ['clouds-texture-uri', undefined],
  ['clouds-scale-x', 2],
  ['clouds-scale-y', 1],
  ['clouds-speed-x', 0.2],
  ['clouds-speed-y', 0.3],
  ['cloudiness', 0.279],
  ['clouds-opacity', 1],
  ['clouds-sharpness', 0.8],
  ['clouds-shading-intensity', 0.8],
  ['clouds-zenith-falloff', 0.339],
  ['clouds-iterations', 3],
  ['clouds-gain', 0.5],
  ['clouds-lacunarity', 2],
  ['clouds-day-color', '#d7dde7'],
  ['clouds-night-color', '#7d616f'],
];

function kebabToCamel(name: string): string {
  return name.replace(/-([a-z])/g, (_, c: string) => c.toUpperCase());
}

function parseSky(el: Element, sink: WarningSink): VemlLiteProceduralSky {
  sink.checkAttributes(
    el,
    SKY_ATTRS.map(([wire]) => wire),
    'environment > background > lite-procedural-sky',
  );
  const sky: VemlLiteProceduralSky = {};
  for (const [wire, fallback] of SKY_ATTRS) {
    const raw = el.getAttribute(wire);
    const key = kebabToCamel(wire);
    if (raw === null) {
      if (fallback !== undefined) sky[key] = fallback;
    } else if (typeof fallback === 'boolean') {
      sky[key] = parseBool(raw, fallback);
    } else if (typeof fallback === 'number') {
      sky[key] = parseNumber(raw, fallback);
    } else {
      sky[key] = raw;
    }
  }
  return sky;
}

function parseEnvironment(
  el: Element | undefined,
  worldDocUrl: string,
  sink: WarningSink,
): VemlEnvironment {
  const environment: VemlEnvironment = { entities: [] };
  if (!el) return environment; // A.7 leniency.
  sink.checkChildren(el, ['background', 'effects', 'spawn', 'locomotion', 'entity'], 'environment');

  const backgroundEl = childNamed(el, 'background');
  if (backgroundEl) {
    sink.checkChildren(
      backgroundEl,
      ['color', 'panorama', 'lite-procedural-sky'],
      'environment > background',
    );
    const colorEl = childNamed(backgroundEl, 'color');
    const panoramaEl = childNamed(backgroundEl, 'panorama');
    const skyEl = childNamed(backgroundEl, 'lite-procedural-sky');
    let background: VemlBackground | undefined;
    if (colorEl) {
      background = { kind: 'color', color: text(colorEl) ?? '' };
    } else if (panoramaEl) {
      const raw = text(panoramaEl);
      if (raw) {
        background = {
          kind: 'panorama',
          panorama: { raw, resolved: resolveWorldUri(raw, worldDocUrl) },
        };
      }
    } else if (skyEl) {
      background = { kind: 'lite-procedural-sky', sky: parseSky(skyEl, sink) };
    }
    if (background) environment.background = background;
  }

  const effectsEl = childNamed(el, 'effects');
  if (effectsEl) {
    sink.checkChildren(effectsEl, ['lite-fog'], 'environment > effects');
    const fogEl = childNamed(effectsEl, 'lite-fog');
    if (fogEl) {
      sink.checkAttributes(
        fogEl,
        ['fog-enabled', 'color', 'density'],
        'environment > effects > lite-fog',
      );
      environment.liteFog = {
        fogEnabled: parseBool(fogEl.getAttribute('fog-enabled'), false),
        color: fogEl.getAttribute('color') ?? 'gray',
        density: parseNumber(fogEl.getAttribute('density'), 0.5),
      };
    }
  }

  // VEML 3.1 spawn — FIRST-CLASS, never a warning (A.10). Parsed only;
  // spawn RESOLUTION happens at scene build.
  const spawnEl = childNamed(el, 'spawn');
  if (spawnEl) {
    sink.checkChildren(spawnEl, ['position', 'rotation'], 'environment > spawn');
    environment.spawn = {
      position: vec3(childNamed(spawnEl, 'position'), DEFAULT_POSITION),
      rotation: quat(childNamed(spawnEl, 'rotation')),
    };
  }

  // VEML 4.0 §5.2 locomotion hints, read AHEAD of the 4.0 retarget: gravity
  // (m/s², positive magnitude) + jump-height (m, apex). An invalid value
  // (non-numeric, negative, non-finite) warns and only THAT attribute is
  // treated as absent — the §2 tolerance rule, matching the conformance
  // reference adapter's veml:5.2:locomotion-invalid recovery.
  const locomotionEl = childNamed(el, 'locomotion');
  if (locomotionEl) {
    sink.checkAttributes(locomotionEl, ['gravity', 'jump-height'], 'environment > locomotion');
    const hint = (attr: string): number | undefined => {
      const raw = locomotionEl.getAttribute(attr);
      if (raw === null) return undefined;
      const n = Number(raw);
      if (raw.trim() === '' || !Number.isFinite(n) || n < 0) {
        sink.add('invalid-attribute-value', `${attr}="${raw}"`, 'environment > locomotion');
        return undefined;
      }
      return n;
    };
    const locomotion: VemlLocomotion = {};
    const gravity = hint('gravity');
    const jumpHeight = hint('jump-height');
    if (gravity !== undefined) locomotion.gravity = gravity;
    if (jumpHeight !== undefined) locomotion.jumpHeight = jumpHeight;
    environment.locomotion = locomotion;
  }

  environment.entities = childrenNamed(el, 'entity').map((child, i) =>
    parseEntity(child, `environment > entity[${i}]`, worldDocUrl, sink),
  );
  return environment;
}

// ---------------------------------------------------------------------------
// Entry point.
// ---------------------------------------------------------------------------

function classifyNamespace(ns: string | null): VemlDeclaredVersion | 'unsupported' {
  if (!ns) return 'none';
  if (ns === VEML_NAMESPACE_3_0) return '3.0';
  if (ns === VEML_NAMESPACE_3_1) return '3.1';
  return 'unsupported';
}

/**
 * Parse VEML document text fetched from `worldDocUrl`.
 * Never throws; all failure modes land in the report.
 */
export function parseVeml(xmlText: string, worldDocUrl: string): VemlParseResult {
  const report: VemlParseReport = {
    url: worldDocUrl,
    declaredVersion: null,
    errors: [],
    warnings: [],
  };
  const fail = (kind: VemlParseError['kind'], message: string): VemlParseResult => {
    report.errors.push({ kind, message, url: worldDocUrl });
    return { ok: false, report };
  };

  // A.3 normalization: undeclared `xsi:` prefixes are fatal to DOMParser but
  // ubiquitous on the wire — inject xmlns:xsi at the root when absent.
  const dom = new DOMParser().parseFromString(normalizeRootTag(xmlText), 'text/xml');

  // A DOMParser failure signal is a <parsererror> that is either the root
  // element or in a browser error namespace (Chrome: XHTML; Firefox/jsdom:
  // mozilla). A document's OWN element named parsererror (null/veml
  // namespace, non-root) is ordinary unknown content per A.8, not a failure.
  const errorNamespaces = [
    'http://www.w3.org/1999/xhtml',
    'http://www.mozilla.org/newlayout/xml/parsererror.xml',
  ];
  const parserError = Array.from(dom.getElementsByTagName('parsererror')).find(
    (e) => e === dom.documentElement || errorNamespaces.includes(e.namespaceURI ?? ''),
  );
  if (parserError) {
    return fail(
      'malformed-xml',
      `Document at ${worldDocUrl} is not well-formed XML: ${
        parserError.textContent?.trim() ?? 'parse error'
      }`,
    );
  }

  const root = dom.documentElement;
  // A.1/A.3: root must be <veml>, case-insensitively, so <VEML> loads too.
  if (root.localName.toLowerCase() !== 'veml') {
    return fail(
      'not-veml',
      `Document at ${worldDocUrl} has root <${root.localName}>, expected <veml>`,
    );
  }

  const version = classifyNamespace(root.namespaceURI);
  if (version === 'unsupported') {
    // Name the found namespace AND the supported ones.
    return fail(
      'unsupported-namespace',
      `Unsupported VEML namespace "${root.namespaceURI}" in document at ${worldDocUrl}. ` +
        `Supported namespaces: "${VEML_NAMESPACE_3_0}" (VEML 3.0), ` +
        `"${VEML_NAMESPACE_3_1}" (VEML 3.1), or no namespace (parsed as VEML 3.1).`,
    );
  }
  report.declaredVersion = version;

  // The document build must uphold the never-throws contract even on
  // pathological input (e.g. entity nesting deep enough to overflow the
  // recursion stack) — convert any escape into a report error.
  try {
    const sink = new WarningSink();
    sink.checkChildren(root, ['metadata', 'environment'], 'veml');
    sink.checkAttributes(root, [], 'veml'); // xmlns/xsi machinery is skipped
    const document: VemlDocument = {
      declaredVersion: version,
      metadata: parseMetadata(childNamed(root, 'metadata'), worldDocUrl, sink),
      environment: parseEnvironment(childNamed(root, 'environment'), worldDocUrl, sink),
    };
    report.warnings.push(...sink.warnings);
    return { ok: true, document, report };
  } catch (err) {
    return fail(
      'malformed-xml',
      `Document at ${worldDocUrl} exceeded parser limits: ${
        err instanceof Error ? err.message : String(err)
      }`,
    );
  }
}
